// One item per due lead. Build a stage-appropriate question for the owning agent.
const r = $input.item.json;
if (!r || !r.conversation_id) { return []; }
const op = r.operation ? ` (${r.operation})` : '';
const lead = r.lead_name || 'el lead';
const prop = r.property_title || 'la propiedad';
let q;
switch (r.prompt_kind) {
  case 'new_2h':
    q = `\u{1F514} Tienes un lead nuevo: *${lead}* por ${prop}${op}. \u00bfYa lo contactaste? Cu\u00e9ntame en qu\u00e9 qued\u00f3 y el pr\u00f3ximo paso.`; break;
  case 'new_24h':
    q = `\u23F0 Recordatorio: *${lead}* (${prop}${op}) sigue sin registrar contacto. \u00bfPudiste comunicarte? \u00bfQu\u00e9 sigue?`; break;
  case 'stalled':
    q = `\u{1F4CB} \u00bfC\u00f3mo va *${lead}* por ${prop}${op}? No hay novedades hace unos d\u00edas. \u00bfEn qu\u00e9 etapa est\u00e1 y cu\u00e1l es el siguiente paso?`; break;
  case 'visit_day':
    q = `\u{1F4C5} Hoy es la visita con *${lead}* por ${prop}${op}. \u00bfSigue en pie? Av\u00edsame c\u00f3mo te va.`; break;
  default:
    q = `\u{1F4CB} \u00bfC\u00f3mo va *${lead}* por ${prop}${op}?`;
}
const accionMap = { new_2h: 'Confirmar primer contacto', new_24h: 'Reintentar contacto', stalled: 'Actualizar estado del lead', visit_day: 'Confirmar visita de hoy' };
const accion = accionMap[r.prompt_kind] || 'Actualizar seguimiento';
return [{ json: { number: r.agent_number, text: q, t_nombre: String(lead), t_telefono: String(r.lead_phone || 'N/D'), t_propiedad: String(prop), t_accion: accion, conversation_id: r.conversation_id, agent_id: r.agent_id, prompt_kind: r.prompt_kind } }];
